export async function createScene(engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0.05, 0.02, 0.18);

  const camera = new BABYLON.ArcRotateCamera("camera", Math.PI / 2, Math.PI / 3, 20, BABYLON.Vector3.Zero(), scene);
  camera.attachControl(canvas, true);

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.8;

  const box = BABYLON.MeshBuilder.CreateBox("box", { size: 1 }, scene);
  box.position.set(-2, 4, 0);

  const tempBox = BABYLON.MeshBuilder.CreateBox("tempBox", { size: 1 }, scene);

  const lightningOptions = {
    segments: 20,
    roughness: 0.4,
    color: new BABYLON.Color3(0.5, 1, 1),
  };

  const glow = new BABYLON.GlowLayer("glow", scene);
  glow.intensity = 1.6;

  let lightningMesh = null;
  let lightningVertexData = null;
  let lightningTimer = 0;
  const lightningInterval = 0.01;

  function generateLightningPoints(source, dest, options) {
    const points = [];
    const segments = options.segments || 20;
    const roughness = options.roughness || 0.5;

    for (let i = 0; i <= segments; i++) {
      const t = i / segments;
      const point = BABYLON.Vector3.Lerp(source, dest, t);
      const offset = new BABYLON.Vector3((Math.random() - 0.5) * roughness, (Math.random() - 0.5) * roughness, (Math.random() - 0.5) * roughness);
      points.push(point.add(offset));
    }

    return points;
  }

  const mouseTarget = new BABYLON.Vector3(0, 0, 0);

  const pickingGround = BABYLON.MeshBuilder.CreateGround(
    "pickingGround",
    {
      width: 1000,
      height: 1000,
    },
    scene
  );
  pickingGround.isPickable = true;
  pickingGround.visibility = 0;

  scene.onPointerMove = function (evt, pickResult) {
    const pick = scene.pick(scene.pointerX, scene.pointerY, (mesh) => mesh === pickingGround);
    if (pick && pick.hit) {
      mouseTarget.copyFrom(pick.pickedPoint);
    }
  };

  scene.onBeforeRenderObservable.add(() => {
    const dt = engine.getDeltaTime() / 1000;
    lightningTimer += dt;

    const time = performance.now() * 0.001;

    box.position.x = -2 + Math.sin(time * 1.3) * 5;
    box.position.y = 4 + Math.cos(time * 1.1) * 3;
    box.position.z = Math.sin(time * 0.8) * 5;

    tempBox.position = mouseTarget.clone();

    if (!lightningMesh) {
      const points = generateLightningPoints(box.position, mouseTarget, lightningOptions);

      lightningMesh = BABYLON.MeshBuilder.CreateLines(
        "lightning",
        {
          points: points,
          updatable: true,
        },
        scene
      );

      const mat = new BABYLON.StandardMaterial("lightMat", scene);
      mat.emissiveColor = lightningOptions.color;
      mat.disableLighting = true;
      lightningMesh.material = mat;
      lightningMesh.isPickable = false;
      lightningMesh.alwaysSelectAsActiveMesh = true;

      lightningVertexData = new Float32Array(points.length * 3);
      for (let i = 0; i < points.length; i++) {
        lightningVertexData[i * 3 + 0] = points[i].x;
        lightningVertexData[i * 3 + 1] = points[i].y;
        lightningVertexData[i * 3 + 2] = points[i].z;
      }
    }

    if (lightningTimer >= lightningInterval) {
      const points = generateLightningPoints(box.position, mouseTarget, lightningOptions);

      for (let i = 0; i < points.length; i++) {
        lightningVertexData[i * 3 + 0] = points[i].x;
        lightningVertexData[i * 3 + 1] = points[i].y;
        lightningVertexData[i * 3 + 2] = points[i].z;
      }
      lightningMesh.updateVerticesData(BABYLON.VertexBuffer.PositionKind, lightningVertexData);
      lightningTimer = 0;
    } else {
      for (let i = 1; i < lightningOptions.segments; i++) {
        lightningVertexData[i * 3 + 0] += (Math.random() - 0.5) * 0.02;
        lightningVertexData[i * 3 + 1] += (Math.random() - 0.5) * 0.02;
        lightningVertexData[i * 3 + 2] += (Math.random() - 0.5) * 0.02;
      }
      lightningMesh.updateVerticesData(BABYLON.VertexBuffer.PositionKind, lightningVertexData);
    }
  });

  return scene;
}
